SELECT ?host ?totalShows WHERE {
  ?show a <http://dbpedia.org/ontology/TelevisionShow> ;
        <http://dbpedia.org/ontology/countryOfOrigin> <http://dbpedia.org/resource/United_Kingdom> ;
        <http://dbpedia.org/ontology/starring> <http://dbpedia.org/resource/Paul_Melba> ;
        <http://dbpedia.org/ontology/host> ?host .
  ?host <http://dbpedia.org/ontology/numberOfShowsHosted> ?totalShows .
  FILTER(?totalShows = 23)
}

SELECT ?publication ?publicationType ?publicationYear ?publisher ?publisherType WHERE {
  ?pub a ?publicationType ;
       dc:creator "Paul Shaw" ;
       dc:title ?title ;
       dc:date ?publicationYear ;
       dc:publisher ?publisher .
  FILTER(CONTAINS(LCASE(?title), "new york subway") && ?publicationYear = 2014)
  ?publisher a ?publisherType .
}

SELECT ?magazine ?isPeriodical WHERE {
  ?magazine a dbo:Periodical .
  FILTER(?magazine IN ("NameOfMagazineThatPublishedPaulShawWork", "National Journal"))
}

SELECT ?publication ?publicationType ?publicationYear ?publisher ?publisherType WHERE {
  ?pub a ?publicationType ;
       dc:creator "Paul Shaw" ;
       dc:title ?title ;
       dc:date ?publicationYear ;
       dc:publisher ?publisher .
  FILTER(CONTAINS(LCASE(?title), "new york subway") && ?publicationYear = 2014)
  ?publisher a ?publisherType .
}

SELECT ?magazine ?isPeriodical WHERE {
  ?magazine a dbo:Periodical .
  FILTER(?magazine IN ("NameOfMagazineThatPublishedPaulShawWork", "National Journal"))
}

SELECT ?movie WHERE {
  ?movie a dbo:Film ;
         dbo:writer dbr:Christopher_B._Landon ;
         dbo:starring dbr:Shia_Labeouf ;
         dbo:releaseDate ?date .
  FILTER(year(?date) = 2007)
} 

ASK {
  dbr:Shia_Labeouf dbo:nationality dbr:United_States .
  dbr:Shia_Labeouf dbo:starring dbr:Even_Stevens .
  dbr:Even_Stevens dbo:firstRun ?premiereDate .
  FILTER(year(?premiereDate) = 2004)
}

