SELECT ?kerberOrigin ?kerberSport ?defendingChampion ?defendingChampionSport WHERE {
  ?kerber wdt:P31 wd:Q5;  # instance of human
          rdfs:label "Angelique Kerber"@en;
          wdt:P19 ?kerberPlaceOfBirth;
          wdt:P641 ?kerberSportEntity.
  ?kerberPlaceOfBirth rdfs:label ?kerberOrigin.
  ?kerberSportEntity rdfs:label ?kerberSport.

  # To confirm Texas native
  FILTER(CONTAINS(LCASE(?kerberOrigin), "texas")).

  # The 2005 China Open - Men's Doubles defending champion info
  ?tournament wdt:P31 wd:Q847017;  # tennis tournament
             rdfs:label "2005 China Open – Men's Doubles"@en;
             wdt:P1346 ?defendingChampionEntity.
  ?defendingChampionEntity rdfs:label ?defendingChampion;
                         wdt:P641 ?defendingChampionSportEntity.
  ?defendingChampionSportEntity rdfs:label ?defendingChampionSport.

  FILTER(CONTAINS(LCASE(?defendingChampionSport), "tennis")).
}
LIMIT 10

